from __future__ import annotations

import json
import os
import uuid
from copy import deepcopy
from datetime import datetime, timezone
from pathlib import Path
from threading import RLock
from typing import Any, Dict, List, Optional

from fastapi import APIRouter, HTTPException, Query
from pydantic import BaseModel, Field


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _ts(value: Optional[str]) -> float:
    if not value:
        return 0.0
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00")).timestamp()
    except Exception:
        return 0.0


def _dump(model: BaseModel) -> Dict[str, Any]:
    if hasattr(model, "model_dump"):
        return model.model_dump(exclude_none=True)
    return model.dict(exclude_none=True)


class HealthSnapshot(BaseModel):
    online_count: int = 0
    network_latency_ms: float = 0.0
    cpu_percent: float = 0.0
    gpu_percent: float = 0.0
    obs_fps: float = 0.0
    tts_queue_depth: int = 0
    status: str = "ok"
    meta: Dict[str, Any] = Field(default_factory=dict)


class SnapshotUpdate(BaseModel):
    online_count: Optional[int] = None
    network_latency_ms: Optional[float] = None
    cpu_percent: Optional[float] = None
    gpu_percent: Optional[float] = None
    obs_fps: Optional[float] = None
    tts_queue_depth: Optional[int] = None
    status: Optional[str] = None
    meta: Dict[str, Any] = Field(default_factory=dict)


class AlertRule(BaseModel):
    id: str = ""
    name: str
    metric: str
    op: str = Field(default="gt", description="gt/gte/lt/lte/eq/ne")
    threshold: float
    severity: str = Field(default="warning", description="info/warning/critical")
    cooldown_seconds: int = 60
    enabled: bool = True
    last_fired_at: Optional[str] = None
    meta: Dict[str, Any] = Field(default_factory=dict)

    def check(self, snapshot: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        if not self.enabled:
            return None
        value = snapshot.get(self.metric)
        if value is None:
            return None
        try:
            left = float(value)
            right = float(self.threshold)
        except Exception:
            return None

        hit = {
            "gt": left > right,
            "gte": left >= right,
            "lt": left < right,
            "lte": left <= right,
            "eq": left == right,
            "ne": left != right,
        }.get(self.op, False)
        if not hit:
            return None

        if self.last_fired_at and self.cooldown_seconds > 0:
            elapsed = datetime.now(timezone.utc).timestamp() - _ts(self.last_fired_at)
            if elapsed < self.cooldown_seconds:
                return None

        return {
            "id": uuid.uuid4().hex,
            "rule_id": self.id,
            "rule_name": self.name,
            "metric": self.metric,
            "op": self.op,
            "threshold": self.threshold,
            "value": left,
            "severity": self.severity,
            "message": f"{self.name}: {self.metric}={left} {self.op} {self.threshold}",
            "created_at": _now(),
        }


class AlertRuleCreate(BaseModel):
    name: str
    metric: str
    op: str = "gt"
    threshold: float
    severity: str = "warning"
    cooldown_seconds: int = 60
    enabled: bool = True
    meta: Dict[str, Any] = Field(default_factory=dict)


class TimelineEvent(BaseModel):
    type: str = "event"
    title: str
    message: str = ""
    severity: str = "info"
    payload: Dict[str, Any] = Field(default_factory=dict)


class DashboardStore:
    def __init__(self, path: Optional[str] = None, max_snapshots: int = 500, max_events: int = 2000):
        default_path = Path("data") / "live_dashboard" / "dashboard.json"
        self.path = Path(path or os.getenv("PHS_LIVE_DASHBOARD_DB", default_path))
        self.max_snapshots = max_snapshots
        self.max_events = max_events
        self.lock = RLock()
        self.data: Dict[str, Any] = {"snapshots": [], "rules": [], "alerts": [], "timeline": []}
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._load()
        self._ensure_default_rules()

    def _load(self) -> None:
        if not self.path.exists():
            self._save()
            return
        try:
            self.data = json.loads(self.path.read_text(encoding="utf-8"))
            for key in ("snapshots", "rules", "alerts", "timeline"):
                self.data.setdefault(key, [])
        except Exception:
            self.path.replace(self.path.with_suffix(".corrupt.json"))
            self.data = {"snapshots": [], "rules": [], "alerts": [], "timeline": []}
            self._save()

    def _save(self) -> None:
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.data, ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(self.path)

    def _ensure_default_rules(self) -> None:
        if self.data.get("rules"):
            return
        defaults = [
            AlertRuleCreate(name="网络延迟过高", metric="network_latency_ms", op="gt", threshold=800, severity="warning"),
            AlertRuleCreate(name="CPU占用过高", metric="cpu_percent", op="gt", threshold=90, severity="warning"),
            AlertRuleCreate(name="GPU占用过高", metric="gpu_percent", op="gt", threshold=95, severity="warning"),
            AlertRuleCreate(name="OBS帧率过低", metric="obs_fps", op="lt", threshold=20, severity="critical"),
            AlertRuleCreate(name="TTS队列堆积", metric="tts_queue_depth", op="gt", threshold=20, severity="warning"),
        ]
        self.data["rules"] = [self._new_rule(x) for x in defaults]
        self._save()

    def _new_rule(self, payload: AlertRuleCreate) -> Dict[str, Any]:
        item = _dump(payload)
        item["id"] = uuid.uuid4().hex
        item["last_fired_at"] = None
        item["created_at"] = _now()
        item["updated_at"] = item["created_at"]
        return item

    def latest_snapshot(self) -> Dict[str, Any]:
        with self.lock:
            if not self.data["snapshots"]:
                return {"id": None, "created_at": None, **_dump(HealthSnapshot())}
            return deepcopy(self.data["snapshots"][-1])

    def add_snapshot(self, payload: HealthSnapshot | SnapshotUpdate) -> Dict[str, Any]:
        base = self.latest_snapshot()
        if base.get("id") is None:
            base = _dump(HealthSnapshot())
        patch = _dump(payload)
        meta = dict(base.get("meta") or {})
        meta.update(patch.pop("meta", {}) or {})
        base.update(patch)
        base["meta"] = meta
        base["id"] = uuid.uuid4().hex
        base["created_at"] = _now()

        with self.lock:
            self.data["snapshots"].append(base)
            self.data["snapshots"] = self.data["snapshots"][-self.max_snapshots:]
            alerts = self.evaluate_alerts_locked(base)
            self._save()
        result = deepcopy(base)
        result["alerts"] = alerts
        return result

    def list_rules(self) -> List[Dict[str, Any]]:
        with self.lock:
            return deepcopy(self.data["rules"])

    def add_rule(self, payload: AlertRuleCreate) -> Dict[str, Any]:
        with self.lock:
            item = self._new_rule(payload)
            self.data["rules"].append(item)
            self._save()
            return deepcopy(item)

    def delete_rule(self, rule_id: str) -> Dict[str, Any]:
        with self.lock:
            for i, item in enumerate(self.data["rules"]):
                if item.get("id") == rule_id:
                    deleted = self.data["rules"].pop(i)
                    self._save()
                    return deepcopy(deleted)
        raise KeyError(rule_id)

    def evaluate_alerts_locked(self, snapshot: Dict[str, Any]) -> List[Dict[str, Any]]:
        hits: List[Dict[str, Any]] = []
        for i, raw in enumerate(self.data["rules"]):
            rule = AlertRule(**raw)
            alert = rule.check(snapshot)
            if not alert:
                continue
            hits.append(alert)
            self.data["rules"][i]["last_fired_at"] = alert["created_at"]
            self.data["alerts"].append(alert)
            self.data["timeline"].append({
                "id": uuid.uuid4().hex,
                "type": "alert",
                "title": alert["rule_name"],
                "message": alert["message"],
                "severity": alert["severity"],
                "payload": alert,
                "created_at": alert["created_at"],
            })
        self.data["alerts"] = self.data["alerts"][-self.max_events:]
        self.data["timeline"] = self.data["timeline"][-self.max_events:]
        return deepcopy(hits)

    def list_alerts(self, limit: int = 100) -> List[Dict[str, Any]]:
        with self.lock:
            return deepcopy(self.data["alerts"][-limit:][::-1])

    def add_timeline(self, payload: TimelineEvent) -> Dict[str, Any]:
        item = _dump(payload)
        item["id"] = uuid.uuid4().hex
        item["created_at"] = _now()
        with self.lock:
            self.data["timeline"].append(item)
            self.data["timeline"] = self.data["timeline"][-self.max_events:]
            self._save()
            return deepcopy(item)

    def list_timeline(self, limit: int = 200, since: Optional[str] = None) -> List[Dict[str, Any]]:
        with self.lock:
            items = deepcopy(self.data["timeline"])
        if since:
            start = _ts(since)
            items = [x for x in items if _ts(x.get("created_at")) >= start]
        return items[-limit:]


class TimelineRecorder:
    def __init__(self, store: DashboardStore):
        self.store = store

    def record(self, event: TimelineEvent) -> Dict[str, Any]:
        return self.store.add_timeline(event)

    def replay(self, limit: int = 200, since: Optional[str] = None) -> List[Dict[str, Any]]:
        return self.store.list_timeline(limit=limit, since=since)


def create_live_dashboard_router(store: Optional[DashboardStore] = None, prefix: str = "") -> APIRouter:
    db = store or DashboardStore()
    timeline = TimelineRecorder(db)
    router = APIRouter(prefix=prefix, tags=["live-dashboard"])

    @router.get("/dashboard/snapshot")
    def get_snapshot() -> Dict[str, Any]:
        item = db.latest_snapshot()
        item["alerts"] = db.list_alerts(limit=20)
        return item

    @router.post("/dashboard/snapshot")
    def post_snapshot(payload: SnapshotUpdate) -> Dict[str, Any]:
        return db.add_snapshot(payload)

    @router.get("/dashboard/alerts")
    def get_alerts(include_rules: bool = True, limit: int = Query(default=100, ge=1, le=500)) -> Dict[str, Any]:
        return {"alerts": db.list_alerts(limit=limit), "rules": db.list_rules() if include_rules else []}

    @router.post("/dashboard/alerts")
    def create_alert_rule(payload: AlertRuleCreate) -> Dict[str, Any]:
        return db.add_rule(payload)

    @router.delete("/dashboard/alerts/{rule_id}")
    def delete_alert_rule(rule_id: str) -> Dict[str, Any]:
        try:
            return {"deleted": True, "item": db.delete_rule(rule_id)}
        except KeyError:
            raise HTTPException(status_code=404, detail="alert rule not found")

    @router.get("/dashboard/timeline")
    def get_timeline(limit: int = Query(default=200, ge=1, le=1000), since: Optional[str] = None) -> Dict[str, Any]:
        items = timeline.replay(limit=limit, since=since)
        return {"items": items, "count": len(items)}

    @router.post("/dashboard/timeline")
    def post_timeline(payload: TimelineEvent) -> Dict[str, Any]:
        return timeline.record(payload)

    return router


class LiveDashboardProvider:
    provider_id = "live_dashboard"
    name = "Live Dashboard"
    version = "0.1.0"

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.store = DashboardStore(self.config.get("db_path"))
        self.timeline = TimelineRecorder(self.store)
        self.router = create_live_dashboard_router(self.store)

    def get_router(self) -> APIRouter:
        return self.router

    def health(self) -> Dict[str, Any]:
        return {
            "provider": self.provider_id,
            "ok": True,
            "db_path": str(self.store.path),
            "snapshot_count": len(self.store.data.get("snapshots", [])),
            "alert_count": len(self.store.data.get("alerts", [])),
        }

    def metadata(self) -> Dict[str, Any]:
        return {
            "id": self.provider_id,
            "name": self.name,
            "version": self.version,
            "routes": ["/dashboard/snapshot", "/dashboard/alerts", "/dashboard/timeline"],
        }


def create_provider(config: Optional[Dict[str, Any]] = None) -> LiveDashboardProvider:
    return LiveDashboardProvider(config)


provider = LiveDashboardProvider()
